{
  "hypotheses": [
    {
      "stance": "bull",
      "mechanism": "若原案續行，三排座純電 SUV 仍需後續製造與模具投資。取消原案可讓 Ford 將資金轉作其他用途。此情境假設純電車投資比重實際下降；現金節省額仍取決於總資本支出及替代專案用款。",
      "target": "Ford",
      "horizon": "2025-10-31",
      "catalyst": "2024-08-21 公告重排投資後，於 2024 年度結束至 2025-10-31 間，查 Ford 年報或投資人簡報是否更新純電車資本支出占比。",
      "prediction": "若調整已於 2024 年度開始落實，Ford 同口徑全年實際純電車資本支出占比應低於公告所述約 40% 的原配置水準，朝約 30% 的計畫靠攏。該占比是投資重排的代理指標，無法歸因單一車款。",
      "invalidation": "若 Ford 截至 2025-10-31 披露的 2024 全年同口徑實際占比仍約為 40% 或更高，則推翻當年已降低比重的假設。僅重申目標或未披露實績，結果仍待驗證。",
      "claim_ids": ["fact:ford-ev-strategy:plans"]
    },
    {
      "stance": "bear",
      "mechanism": "取消原案使原定投入生產的製造與供應商模具資產失去預期用途。相較續行原案，若 Ford 因取消而減記，將直接壓低當季稅前獲利。公司估計減記約 4 億美元，實際現金支出另待核實。",
      "target": "Ford",
      "horizon": "2025-10-31",
      "catalyst": "Ford 預估於 2024 年第三季認列減記，首個核對時點為該季結束後公布的 Ford 季報及財報說明。",
      "prediction": "截至 2025-10-31，Ford 財報應可核對 2024 年第三季就該 SUV 製造與供應商模具資產認列正額減記，並以公告估計的約 4 億美元衡量實際獲利衝擊。",
      "invalidation": "若 Ford 截至 2025-10-31 明確披露該批資產在 2024 年第三季的減記為零，即推翻當季獲利受此項目拖累的假設。財報未單列金額仍無法判定。",
      "claim_ids": ["fact:ford-ev-8k:charges"]
    }
  ],
  "assessment": {
    "thesis": "Ford 已宣布取消三排座純電 SUV，短期稅前獲利面臨專案資產減記，後續資金調度能改善多少，取決於避免的投資與退出所需現金。",
    "key_gap": "相較續行原案，取消專案究竟能淨省多少現金？若 Ford 未公開量化，須取得原案剩餘投資預算、替代專案用款及退出付款紀錄才能估算。",
    "next_check": "先查 Ford 2024 年第三季 10-Q 及財報說明，核對 8-K 預估的約 4 億美元減記是否入帳，並分辨另行認列的費用與實際付款。",
    "evidence_limits": [
      {
        "evidence_id": "ford-ev-8k:charges",
        "limit": "8-K 支持第三季減記約 4 億美元的估計，另有最多約 15 億美元的可能費用及現金支出。上限無法視為已認列費用或已付款金額。"
      },
      {
        "evidence_id": "ford-ev-strategy:plans",
        "limit": "策略公告列出純電車資本支出占比由約 40% 降至約 30% 的計畫，未指定達標年度或披露實際節省額。2026 年廂型車投產及 2027 年皮卡推出均為研究期限後的計畫，無從據此確認訂單、交付、採用或營收。"
      }
    ],
    "public_checks": [
      {
        "metric": "三排座純電 SUV 製造與供應商模具資產的實際減記額",
        "source_to_watch": "Ford 向 SEC 提交的 2024 年第三季 10-Q 及當季財報說明",
        "window": "2024 年第三季結束後首次季報，最遲核對至 2025-10-31",
        "impact_on_thesis": "專案減記入帳可確認當季獲利受損，金額與約 4 億美元估計的差距決定衝擊大小。減記本身無法衡量退出付款。",
        "evidence_ids": ["ford-ev-8k:charges"]
      },
      {
        "metric": "2024 全年純電車資本支出占總資本支出的實際比重",
        "source_to_watch": "Ford 年報或投資人簡報。策略公告已使用此占比描述配置計畫，實績是否單列仍待核對。",
        "window": "2024 年度結束後至 2025-10-31",
        "impact_on_thesis": "同口徑實績低於約 40% 支持投資已開始重排，仍約為 40% 或更高則削弱此判斷。占比只反映整體配置，單一 SUV 的節省額仍待專案資料。",
        "evidence_ids": ["ford-ev-strategy:plans"]
      }
    ],
    "supply_chain": [],
    "trade_opportunities": []
  }
}
